import java.util.*;
final class Evaluator {
    sealed interface Value permits IntegerValue, BooleanValue, StringValue, PairValue, ListValue,
        Closure, Builtin {}
    record IntegerValue(int value) implements Value {}
    record BooleanValue(boolean value) implements Value {}
    record StringValue(String value) implements Value {}
    record PairValue(Value first, Value second) implements Value {}
    record ListValue(List<Value> elements) implements Value {
        ListValue { elements = List.copyOf(elements); }
    }
    static final class Closure implements Value {
        String parameter;
        Parser.Expr body;
        Map<String, Value> environment;
        Closure(String parameter, Parser.Expr body, Map<String, Value> environment) {
            this.parameter = parameter;
            this.body = body;
            this.environment = environment;
        }
    }
    @FunctionalInterface
    interface Behavior {
        Value apply(Value value, Lexer.Position position);
    }
    record Builtin(Behavior behavior) implements Value {}
    static final class RuntimeFailure extends RuntimeException {
        Lexer.Position position;
        RuntimeFailure(Lexer.Position position, String message) {
            super(message);
            this.position = position;
        }
    }
    static IntegerValue checked(long value, Lexer.Position position) {
        if (value < Integer.MIN_VALUE || value > Integer.MAX_VALUE)
            throw new RuntimeFailure(position, "integer overflow");
        return new IntegerValue((int)value);
    }
    static Value literal(String kind, String value) {
        return switch (kind) {
            case "integer" -> new IntegerValue(Integer.parseInt(value));
            case "boolean" -> new BooleanValue(Boolean.parseBoolean(value));
            default -> new StringValue(value);
        };
    }
    static int compare(Value first, Value second, Lexer.Position position) {
        if (first instanceof Closure || first instanceof Builtin)
            throw new RuntimeFailure(position, "functional value compared");
        if (first instanceof IntegerValue a)
            return Integer.compare(a.value(), ((IntegerValue)second).value());
        if (first instanceof BooleanValue a)
            return Boolean.compare(a.value(), ((BooleanValue)second).value());
        if (first instanceof StringValue a)
            return a.value().compareTo(((StringValue)second).value());
        if (first instanceof PairValue a) {
            PairValue b = (PairValue)second;
            int order = compare(a.first(), b.first(), position);
            return order == 0 ? compare(a.second(), b.second(), position) : order;
        }
        List<Value> a = ((ListValue)first).elements(), b = ((ListValue)second).elements();
        for (int i = 0; i < Math.min(a.size(), b.size()); i++) {
            int order = compare(a.get(i), b.get(i), position);
            if (order != 0)
                return order;
        }
        return Integer.compare(a.size(), b.size());
    }
    static Value binary(String operator, Value first, Value second, Lexer.Position position) {
        if (Set.of("+", "-", "*", "/", "mod").contains(operator)) {
            long a = ((IntegerValue)first).value(), b = ((IntegerValue)second).value();
            if ((operator.equals("/") || operator.equals("mod")) && b == 0)
                throw new RuntimeFailure(position, "division by zero");
            return checked(switch (operator) {
                case "+" -> a + b;
                case "-" -> a - b;
                case "*" -> a *b;
                case "/" -> a / b;
                default -> a % b;
            }, position);
        }
        if (operator.equals("^"))
            return new StringValue(((StringValue)first).value() + ((StringValue)second).value());
        if (operator.equals("::")) {
            List<Value> values = new ArrayList<>();
            values.add(first);
            values.addAll(((ListValue)second).elements());
            return new ListValue(values);
        }
        int order = compare(first, second, position);
        return new BooleanValue(switch (operator) {
            case "=" -> order == 0;
            case "<>" -> order != 0;
            case "<" -> order < 0;
            case ">" -> order > 0;
            case "<=" -> order <= 0;
            default -> order >= 0;
        });
    }
    static boolean matches(Parser.Pattern pattern, Value value, Map<String, Value> bindings) {
        if (pattern instanceof Parser.Wildcard)
            return true;
        if (pattern instanceof Parser.PatternName name) {
            bindings.put(name.token().spelling(), value);
            return true;
        }
        if (pattern instanceof Parser.PatternLiteral constant)
            return literal(constant.kind(), constant.value()).equals(value);
        if (pattern instanceof Parser.Cons cons) {
            List<Value> list = ((ListValue)value).elements();
            return !list.isEmpty() && matches(cons.first(), list.getFirst(), bindings) &&
                matches(cons.rest(), new ListValue(list.subList(1, list.size())), bindings);
        }
        if (pattern instanceof Parser.PatternList list) {
            List<Value> values = ((ListValue)value).elements();
            if (values.size() != list.elements().size())
                return false;
            for (int i = 0; i < values.size(); i++)
                if (!matches(list.elements().get(i), values.get(i), bindings))
                    return false;
            return true;
        }
        Parser.PatternPair pair = (Parser.PatternPair)pattern;
        PairValue values = (PairValue)value;
        return matches(pair.first(), values.first(), bindings) &&
            matches(pair.second(), values.second(), bindings);
    }
    int calls;
    Value expression(Parser.Expr expression, Map<String, Value> environment) {
        return switch (expression) {
            case Parser.Literal literal -> literal(literal.kind(), literal.value());
            case Parser.Name name -> environment.get(name.token().spelling());
            case Parser.Fun function ->
                new Closure(function.parameter().spelling(), function.body(),
                            new HashMap<>(environment));
            case Parser.Apply application -> {
                Value function = expression(application.function(), environment),
                      argument = expression(application.argument(), environment);
                calls++;
                if (function instanceof Builtin builtin)
                    yield builtin.behavior().apply(argument, application.position());
                Closure closure = (Closure)function;
                Map<String, Value> inner = new HashMap<>(closure.environment);
                if (!closure.parameter.equals("_"))
                    inner.put(closure.parameter, argument);
                yield expression(closure.body, inner);
            }
            case Parser.Binary binary -> {
                Value first = expression(binary.left(), environment);
                String operator = binary.operator().spelling();
                if (operator.equals("&&"))
                    yield((BooleanValue)first).value() ? expression(binary.right(), environment)
                                                       : new BooleanValue(false);
                if (operator.equals("||"))
                    yield((BooleanValue)first).value() ? new BooleanValue(true)
                                                       : expression(binary.right(), environment);
                Value second = expression(binary.right(), environment);
                yield binary(operator, first, second, binary.operator().position());
            }
            case Parser.Negate negate ->
                checked(-(long)((IntegerValue)expression(negate.operand(), environment)).value(),
                        negate.operator().position());
            case Parser.Conditional conditional ->
                expression(((BooleanValue)expression(conditional.condition(), environment)).value()
                               ? conditional.yes()
                               : conditional.no(),
                           environment);
            case Parser.Pair pair -> {
                Value first = expression(pair.first(), environment),
                      second = expression(pair.second(), environment);
                yield new PairValue(first, second);
            }
            case Parser.ListExpr list -> {
                List<Value> values = new ArrayList<>();
                for (Parser.Expr child : list.elements())
                    values.add(expression(child, environment));
                yield new ListValue(values);
            }
            case Parser.Match match -> {
                Value value = expression(match.matched(), environment);
                Value result = null;
                for (Parser.Arm arm : match.arms()) {
                    Map<String, Value> bindings = new HashMap<>();
                    if (matches(arm.pattern(), value, bindings)) {
                        Map<String, Value> inner = new HashMap<>(environment);
                        inner.putAll(bindings);
                        result = expression(arm.expression(), inner);
                        break;
                    }
                }
                if (result == null)
                    throw new RuntimeFailure(match.position(), "match failure");
                yield result;
            }
            case Parser.Let let -> expression(let.body(), group(let.group(), environment));
        };
    }
    Map<String, Value> group(Parser.Group group, Map<String, Value> environment) {
        Map<String, Value> result = new HashMap<>(environment);
        if (group.recPosition() != null)
            for (Parser.Binding binding : group.bindings()) {
                Parser.Fun function = (Parser.Fun)binding.expression;
                result.put(binding.name(),
                           new Closure(function.parameter().spelling(), function.body(), result));
            }
        else {
            List<Value> values = new ArrayList<>();
            for (Parser.Binding binding : group.bindings())
                values.add(expression(binding.expression, environment));
            for (int i = 0; i < values.size(); i++)
                result.put(group.bindings().get(i).name(), values.get(i));
        }
        return result;
    }
}

import java.util.*;
final class Inference {
    static final class Error extends RuntimeException {
        String kind, name;
        Lexer.Position position;
        Unifier.Type expected, found;
        Unifier.Failure failure;
        Set<String> candidates;
        Error(String kind, Lexer.Position position) {
            this.kind = kind;
            this.position = position;
        }
        Error named(String name) {
            this.name = name;
            return this;
        }
    }
    record OperatorTypes(Unifier.Type first, Unifier.Type second, Unifier.Type result) {}
    static OperatorTypes operatorTypes(String operator) {
        if (Set.of("+", "-", "*", "/", "mod").contains(operator))
            return new OperatorTypes(Unifier.INT, Unifier.INT, Unifier.INT);
        if (operator.equals("^"))
            return new OperatorTypes(Unifier.STRING, Unifier.STRING, Unifier.STRING);
        if (Set.of("&&", "||").contains(operator))
            return new OperatorTypes(Unifier.BOOL, Unifier.BOOL, Unifier.BOOL);
        Unifier.Variable variable = new Unifier.Variable();
        if (operator.equals("::")) {
            Unifier.Type list = new Unifier.Construct("list", variable);
            return new OperatorTypes(variable, list, list);
        }
        return new OperatorTypes(variable, variable, Unifier.BOOL);
    }
    List<Parser.Binding> localBindings = new ArrayList<>();
    Map<Parser.Expr, Unifier.Type> inferred = new IdentityHashMap<>();
    void check(Unifier.Type expected, Unifier.Type found, Lexer.Position position) {
        try {
            Unifier.unify(expected, found);
        } catch (Unifier.Failure failure) {
            Error error = new Error("check", position);
            error.expected = expected;
            error.found = found;
            error.failure = failure;
            throw error;
        }
    }
    Unifier.Type expression(Parser.Expr expression, Map<String, Unifier.Scheme> environment) {
        Unifier.Type result;
        switch (expression) {
        case Parser.Literal literal -> result = literalType(literal.kind());
        case Parser.Name name -> {
            Unifier.Scheme scheme = environment.get(name.token().spelling());
            if (scheme == null) {
                Error error = new Error("unbound", name.position()).named(name.token().spelling());
                error.candidates = new TreeSet<>(environment.keySet());
                throw error;
            }
            result = Unifier.instantiate(scheme);
        }
        case Parser.Fun function -> {
            Unifier.Variable argument = new Unifier.Variable();
            Map<String, Unifier.Scheme> inner = new HashMap<>(environment);
            if (!function.parameter().spelling().equals("_"))
                inner.put(function.parameter().spelling(), new Unifier.Scheme(argument));
            result =
                new Unifier.Construct("function", argument, expression(function.body(), inner));
        }
        case Parser.Apply application -> {
            Unifier.Type function =
                             Unifier.resolve(expression(application.function(), environment)),
                         argument;
            if (function instanceof Unifier.Variable variable) {
                argument = new Unifier.Variable();
                result = new Unifier.Variable();
                variable.binding = new Unifier.Construct("function", argument, result);
            } else if (function instanceof Unifier.Construct construct &&
                       construct.kind().equals("function")) {
                argument = construct.children().get(0);
                result = construct.children().get(1);
            } else {
                Error error = new Error("not_function", application.function().position());
                error.found = function;
                throw error;
            }
            check(argument, expression(application.argument(), environment),
                  application.argument().position());
        }
        case Parser.Binary binary -> {
            OperatorTypes operator = operatorTypes(binary.operator().spelling());
            check(operator.first(), expression(binary.left(), environment),
                  binary.left().position());
            check(operator.second(), expression(binary.right(), environment),
                  binary.right().position());
            result = operator.result();
        }
        case Parser.Negate negate -> {
            check(Unifier.INT, expression(negate.operand(), environment),
                  negate.operand().position());
            result = Unifier.INT;
        }
        case Parser.Conditional conditional -> {
            check(Unifier.BOOL, expression(conditional.condition(), environment),
                  conditional.condition().position());
            result = expression(conditional.yes(), environment);
            Unifier.Type found = expression(conditional.no(), environment);
            check(result, found, conditional.no().position());
        }
        case Parser.Pair pair -> {
            Unifier.Type first = expression(pair.first(), environment),
                         second = expression(pair.second(), environment);
            result = new Unifier.Construct("pair", first, second);
        }
        case Parser.ListExpr list -> {
            Unifier.Variable element = new Unifier.Variable();
            for (Parser.Expr child : list.elements())
                check(element, expression(child, environment), child.position());
            result = new Unifier.Construct("list", element);
        }
        case Parser.Match match -> {
            Unifier.Type matched = expression(match.matched(), environment);
            result = new Unifier.Variable();
            for (Parser.Arm arm : match.arms()) {
                Map<String, Unifier.Type> bindings = new HashMap<>();
                Unifier.Type pattern = pattern(arm.pattern(), bindings);
                check(matched, pattern, arm.pattern().position());
                Map<String, Unifier.Scheme> inner = new HashMap<>(environment);
                for (var entry : bindings.entrySet())
                    inner.put(entry.getKey(), new Unifier.Scheme(entry.getValue()));
                check(result, expression(arm.expression(), inner), arm.expression().position());
            }
        }
        case Parser.Let let -> {
            Map<String, Unifier.Scheme> inner = group(let.group(), environment, true);
            result = expression(let.body(), inner);
        }
        }
        inferred.put(expression, result);
        return result;
    }
    static Unifier.Type literalType(String kind) {
        return switch (kind) {
            case "integer" -> Unifier.INT;
            case "boolean" -> Unifier.BOOL;
            default -> Unifier.STRING;
        };
    }
    Unifier.Type pattern(Parser.Pattern pattern, Map<String, Unifier.Type> bindings) {
        if (pattern instanceof Parser.Wildcard)
            return new Unifier.Variable();
        if (pattern instanceof Parser.PatternName name) {
            String value = name.token().spelling();
            if (bindings.containsKey(value))
                throw new Error("duplicate_pattern", name.position()).named(value);
            Unifier.Type result = new Unifier.Variable();
            bindings.put(value, result);
            return result;
        }
        if (pattern instanceof Parser.PatternLiteral literal)
            return literalType(literal.kind());
        if (pattern instanceof Parser.PatternPair pair) {
            Unifier.Type first = pattern(pair.first(), bindings),
                         second = pattern(pair.second(), bindings);
            return new Unifier.Construct("pair", first, second);
        }
        Unifier.Type element = new Unifier.Variable(), sequence =
                                                           new Unifier.Construct("list", element);
        if (pattern instanceof Parser.Cons cons) {
            check(element, pattern(cons.first(), bindings), cons.first().position());
            check(sequence, pattern(cons.rest(), bindings), cons.rest().position());
        } else
            for (Parser.Pattern child : ((Parser.PatternList)pattern).elements())
                check(element, pattern(child, bindings), child.position());
        return sequence;
    }
    Map<String, Unifier.Scheme> group(Parser.Group group, Map<String, Unifier.Scheme> environment,
                                      boolean local) {
        Set<String> names = new HashSet<>();
        for (Parser.Binding binding : group.bindings()) {
            if (!names.add(binding.name()))
                throw new Error("duplicate_let", binding.position()).named(binding.name());
            if (group.recPosition() != null && !(binding.expression instanceof Parser.Fun))
                throw new Error("recursive_function", binding.position()).named(binding.name());
        }
        List<Unifier.Type> types = new ArrayList<>();
        if (group.recPosition() == null)
            for (Parser.Binding binding : group.bindings())
                types.add(expression(binding.expression, environment));
        else {
            Map<String, Unifier.Scheme> recursive = new HashMap<>(environment);
            for (Parser.Binding binding : group.bindings()) {
                Unifier.Type variable = new Unifier.Variable();
                types.add(variable);
                recursive.put(binding.name(), new Unifier.Scheme(variable));
            }
            for (int i = 0; i < group.bindings().size(); i++) {
                Parser.Binding binding = group.bindings().get(i);
                check(types.get(i), expression(binding.expression, recursive), binding.position());
            }
        }
        Map<String, Unifier.Scheme> result = new HashMap<>(environment);
        for (int i = 0; i < types.size(); i++) {
            Parser.Binding binding = group.bindings().get(i);
            binding.scheme = Unifier.generalize(types.get(i), environment);
            result.put(binding.name(), binding.scheme);
        }
        if (local)
            localBindings.addAll(group.bindings());
        return result;
    }
}

import java.util.*;
final class Lexer {
    record Position(String file, int line, int column) implements Comparable<Position> {
        public int compareTo(Position other) {
            int order = file.compareTo(other.file);
            if (order == 0)
                order = Integer.compare(line, other.line);
            return order == 0 ? Integer.compare(column, other.column) : order;
        }
    }
    record Token(String kind, String spelling, String value, Position position) {
        boolean isName() { return kind.equals("identifier") && !spelling.equals("_"); }
    }
    static final Set<String>
        KEYWORDS =
            Set.of("let rec and in fun if then else match with true false mod val".split(" ")),
        SYMBOLS = Set.of(";; -> :: : || && <= >= <> ; = < > + - * / ^ ( ) [ ] , |".split(" "));
    static boolean letter(char c) { return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z'; }
    static boolean word(char c) { return letter(c) || c >= '0' && c <= '9' || c == '_'; }
    static List<Token> tokenize(String source, String file) {
        List<Token> tokens = new ArrayList<>();
        int index = 0, line = 1, column = 1;
        while (index < source.length()) {
            int start = index;
            Position position = new Position(file, line, column);
            char character = source.charAt(index);
            String kind = null, value = null;
            if (character == ' ' || character == '\n')
                index++;
            else if (source.startsWith("(*", index)) {
                int closing = source.indexOf("*)", index + 2);
                if (closing < 0) {
                    kind = "invalid";
                    value = "unterminated comment";
                    index = source.length();
                } else
                    index = closing + 2;
            } else if (character >= '0' && character <= '9') {
                index++;
                while (index < source.length() && source.charAt(index) >= '0' &&
                       source.charAt(index) <= '9')
                    index++;
                String digits = source.substring(start, index).replaceFirst("^0+", "");
                if (digits.isEmpty())
                    digits = "0";
                if (digits.length() > 10 ||
                    digits.length() == 10 && digits.compareTo("2147483647") > 0) {
                    kind = "invalid";
                    value = "integer literal too large";
                } else {
                    kind = "integer";
                    value = digits;
                }
            } else if (letter(character) || character == '_') {
                index++;
                while (index < source.length() &&
                       (word(source.charAt(index)) || source.charAt(index) == '\''))
                    index++;
                value = source.substring(start, index);
                kind = KEYWORDS.contains(value) ? value : "identifier";
            } else if (character == '\'' && index + 1 < source.length() &&
                       source.charAt(index + 1) >= 'a' && source.charAt(index + 1) <= 'z') {
                index += 2;
                while (index < source.length() && word(source.charAt(index)))
                    index++;
                kind = "type_variable";
                value = source.substring(start, index);
            } else if (character == '"') {
                index++;
                StringBuilder decoded = new StringBuilder();
                boolean invalid = false;
                while (index < source.length() && source.charAt(index) != '"' &&
                       source.charAt(index) != '\n') {
                    char c = source.charAt(index);
                    if (c == '\\' && index + 1 < source.length() &&
                        source.charAt(index + 1) != '\n') {
                        char escape = source.charAt(index + 1);
                        switch (escape) {
                        case 'n' -> decoded.append('\n');
                        case 't' -> decoded.append('\t');
                        case '\\' -> decoded.append('\\');
                        case '"' -> decoded.append('"');
                        default -> invalid = true;
                        }
                        index += 2;
                    } else {
                        decoded.append(c);
                        index++;
                    }
                }
                if (index == source.length() || source.charAt(index) == '\n') {
                    kind = "invalid";
                    value = "unterminated string";
                } else {
                    index++;
                    kind = invalid ? "invalid" : "string";
                    value = invalid ? "invalid escape sequence" : decoded.toString();
                }
            } else {
                String symbol =
                    index + 1 < source.length() ? source.substring(index, index + 2) : "";
                if (SYMBOLS.contains(symbol))
                    index += 2;
                else {
                    symbol = String.valueOf(character);
                    index++;
                }
                if (SYMBOLS.contains(symbol))
                    kind = value = symbol;
                else {
                    kind = "invalid";
                    value = "illegal character '" + character + "'";
                }
            }
            String consumed = source.substring(start, index);
            if (kind != null)
                tokens.add(new Token(kind, consumed, value, position));
            for (int i = start; i < index; i++)
                if (source.charAt(i) == '\n') {
                    line++;
                    column = 1;
                } else
                    column++;
        }
        tokens.add(new Token("EOF", "", null, new Position(file, line, 1)));
        return tokens;
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class Main {
    static String quoted(String value) {
        return "\"" +
            value.replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\n", "\\n")
                .replace("\t", "\\t") +
            "\"";
    }
    static String printValue(Evaluator.Value value) {
        return switch (value) {
            case Evaluator.IntegerValue integer -> Integer.toString(integer.value());
            case Evaluator.BooleanValue bool -> Boolean.toString(bool.value());
            case Evaluator.StringValue string -> quoted(string.value());
            case Evaluator.PairValue pair ->
                "(" + printValue(pair.first()) + ", " + printValue(pair.second()) + ")";
            case Evaluator.ListValue list -> {
                StringJoiner result = new StringJoiner("; ");
                for (Evaluator.Value child : list.elements())
                    result.add(printValue(child));
                yield "[" + result + "]";
            }
            default -> "<fun>";
        };
    }
    static final class TypePrinter {
        Map<Unifier.Variable, String> names = new IdentityHashMap<>();
        Set<Unifier.Variable> quantified;
        TypePrinter() {}
        TypePrinter(Set<Unifier.Variable> quantified) { this.quantified = quantified; }
        String print(Unifier.Type type) {
            type = Unifier.resolve(type);
            if (type instanceof Unifier.Variable variable) {
                if (!names.containsKey(variable)) {
                    int index = names.size();
                    String prefix =
                        quantified != null && !quantified.contains(variable) ? "'_" : "'";
                    names.put(variable, prefix + (char)('a' + index % 26) +
                                            (index >= 26 ? Integer.toString(index / 26) : ""));
                }
                return names.get(variable);
            }
            Unifier.Construct construct = (Unifier.Construct)type;
            String kind = construct.kind();
            if (Set.of("int", "bool", "string").contains(kind))
                return kind;
            Unifier.Type first = Unifier.resolve(construct.children().get(0));
            String left = print(first),
                   firstKind = first instanceof Unifier.Construct child ? child.kind() : "variable";
            if (kind.equals("list"))
                return (Set.of("pair", "function").contains(firstKind) ? "(" + left + ")" : left) +
                    " list";
            Unifier.Type second = Unifier.resolve(construct.children().get(1));
            String right = print(second), secondKind = second instanceof Unifier.Construct child
                                                           ? child.kind()
                                                           : "variable";
            if (kind.equals("pair")) {
                if (Set.of("pair", "function").contains(firstKind))
                    left = "(" + left + ")";
                if (Set.of("pair", "function").contains(secondKind))
                    right = "(" + right + ")";
                return left + " * " + right;
            }
            return (firstKind.equals("function") ? "(" + left + ")" : left) + " -> " + right;
        }
    }
    static String declaredKind(Parser.TypeExpr type) {
        return type instanceof Parser.TypeConstructor constructor ? constructor.kind() : "atom";
    }
    static String formatDeclared(Parser.TypeExpr type) {
        if (type instanceof Parser.TypeName name)
            return name.name();
        if (type instanceof Parser.TypeVariableName variable)
            return variable.spelling();
        Parser.TypeConstructor constructor = (Parser.TypeConstructor)type;
        Parser.TypeExpr first = constructor.children().get(0);
        String left = formatDeclared(first);
        if (constructor.kind().equals("list"))
            return (Set.of("pair", "function").contains(declaredKind(first)) ? "(" + left + ")"
                                                                             : left) +
                " list";
        Parser.TypeExpr second = constructor.children().get(1);
        String right = formatDeclared(second);
        if (constructor.kind().equals("pair")) {
            if (Set.of("pair", "function").contains(declaredKind(first)))
                left = "(" + left + ")";
            if (Set.of("pair", "function").contains(declaredKind(second)))
                right = "(" + right + ")";
            return left + " * " + right;
        }
        return (declaredKind(first).equals("function") ? "(" + left + ")" : left) + " -> " + right;
    }
    static Unifier.Type signatureType(Parser.TypeExpr type,
                                      Map<String, Unifier.Variable> variables) {
        if (type instanceof Parser.TypeVariableName variable)
            return variables.computeIfAbsent(variable.spelling(),
                                             ignored -> new Unifier.Variable());
        if (type instanceof Parser.TypeName name)
            return new Unifier.Construct(name.name());
        Parser.TypeConstructor constructor = (Parser.TypeConstructor)type;
        List<Unifier.Type> children = new ArrayList<>();
        for (Parser.TypeExpr child : constructor.children())
            children.add(signatureType(child, variables));
        return new Unifier.Construct(constructor.kind(), children);
    }
    static boolean identical(Unifier.Type first, Unifier.Type second) {
        first = Unifier.resolve(first);
        second = Unifier.resolve(second);
        if (first instanceof Unifier.Variable || second instanceof Unifier.Variable)
            return first == second;
        Unifier.Construct a = (Unifier.Construct)first, b = (Unifier.Construct)second;
        if (!a.kind().equals(b.kind()))
            return false;
        for (int i = 0; i < a.children().size(); i++)
            if (!identical(a.children().get(i), b.children().get(i)))
                return false;
        return true;
    }
    static boolean signatureMatches(Unifier.Type inferred, Unifier.Type declared,
                                    Map<Unifier.Variable, Unifier.Type> assignments) {
        inferred = Unifier.resolve(inferred);
        declared = Unifier.resolve(declared);
        if (inferred instanceof Unifier.Variable variable) {
            if (assignments.containsKey(variable))
                return identical(assignments.get(variable), declared);
            assignments.put(variable, declared);
            return true;
        }
        if (declared instanceof Unifier.Variable)
            return false;
        Unifier.Construct a = (Unifier.Construct)inferred, b = (Unifier.Construct)declared;
        if (!a.kind().equals(b.kind()))
            return false;
        for (int i = 0; i < a.children().size(); i++)
            if (!signatureMatches(a.children().get(i), b.children().get(i), assignments))
                return false;
        return true;
    }
    static void checkSignatures(Parser.Group group, List<Parser.Signature> signatures) {
        for (int i = 0; i < group.bindings().size(); i++) {
            Parser.Signature signature = signatures.get(i);
            if (signature == null)
                continue;
            Parser.Binding binding = group.bindings().get(i);
            Unifier.Type declared = signatureType(signature.declared(), new HashMap<>()),
                         inferred = binding.scheme.value();
            if (!signatureMatches(inferred, declared, new IdentityHashMap<>())) {
                Inference.Error error =
                    new Inference.Error("signature", binding.position()).named(binding.name());
                error.expected = inferred;
                error.found = declared;
                throw error;
            }
            binding.scheme = new Unifier.Scheme(declared, Unifier.free(declared));
        }
    }
    static int editDistance(String a, String b) {
        int[] previous = new int[b.length() + 1];
        for (int i = 0; i < previous.length; i++)
            previous[i] = i;
        for (int i = 1; i <= a.length(); i++) {
            int[] current = new int[b.length() + 1];
            current[0] = i;
            for (int j = 1; j <= b.length(); j++)
                current[j] =
                    Math.min(Math.min(current[j - 1] + 1, previous[j] + 1),
                             previous[j - 1] + (a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1));
            previous = current;
        }
        return previous[b.length()];
    }
    static String candidate(String name, Set<String> candidates) {
        String chosen = null;
        int best = 3;
        for (String candidate : new TreeSet<>(candidates)) {
            int distance = editDistance(name, candidate);
            if (distance <= 2 && distance < name.length() && distance < best) {
                best = distance;
                chosen = candidate;
            }
        }
        return chosen;
    }
    static String typeError(Inference.Error error) {
        TypePrinter printer = new TypePrinter();
        if (error.kind.equals("unbound")) {
            String candidate = candidate(error.name, error.candidates);
            return "unbound variable '" + error.name + "'" +
                (candidate == null ? "" : " (did you mean '" + candidate + "'?)");
        }
        if (error.kind.equals("not_function"))
            return "expected a function but found " + printer.print(error.found);
        if (error.kind.equals("check")) {
            String message = "expected " + printer.print(error.expected) + " but found " +
                             printer.print(error.found);
            Unifier.Failure failure = error.failure;
            if (failure.infinite) {
                Unifier.Type variable = failure.expected, value = failure.found;
                if (!(variable instanceof Unifier.Variable)) {
                    variable = failure.found;
                    value = failure.expected;
                }
                message += " (infinite type " + printer.print(variable) + " = " +
                           printer.print(value) + ")";
            } else if (failure.nested)
                message += " (" + printer.print(failure.expected) + " vs " +
                           printer.print(failure.found) + ")";
            return message;
        }
        return switch (error.kind) {
            case "duplicate_pattern" ->
                "variable '" + error.name + "' is bound twice in this pattern";
            case "duplicate_let" -> "variable '" + error.name + "' is bound twice in this let";
            case "recursive_function" -> "'" + error.name + "' in let rec must be a function";
            default ->
                "'" + error.name + "' has type " + printer.print(error.expected) +
                    " but its signature is " + printer.print(error.found);
        };
    }
    record Environments(Map<String, Unifier.Scheme> types, Map<String, Evaluator.Value> values) {}
    static Environments builtins() {
        Map<String, Unifier.Scheme> types = new HashMap<>();
        for (String name : List.of("fst", "snd")) {
            Unifier.Variable a = new Unifier.Variable(), b = new Unifier.Variable();
            types.put(name, new Unifier.Scheme(new Unifier.Construct(
                                                   "function", new Unifier.Construct("pair", a, b),
                                                   name.equals("fst") ? a : b),
                                               Set.of(a, b)));
        }
        types.put("not", new Unifier.Scheme(
                             new Unifier.Construct("function", Unifier.BOOL, Unifier.BOOL)));
        types.put("string_of_int", new Unifier.Scheme(new Unifier.Construct("function", Unifier.INT,
                                                                            Unifier.STRING)));
        Unifier.Variable result = new Unifier.Variable();
        types.put("failwith",
                  new Unifier.Scheme(new Unifier.Construct("function", Unifier.STRING, result),
                                     Set.of(result)));
        Map<String, Evaluator.Value> values = new HashMap<>();
        values.put("fst", new Evaluator.Builtin(
                              (value, position) -> ((Evaluator.PairValue)value).first()));
        values.put("snd", new Evaluator.Builtin(
                              (value, position) -> ((Evaluator.PairValue)value).second()));
        values.put("not", new Evaluator.Builtin((value, position)
                                                    -> new Evaluator.BooleanValue(
                                                        !((Evaluator.BooleanValue)value).value())));
        values.put("string_of_int",
                   new Evaluator.Builtin((value, position)
                                             -> new Evaluator.StringValue(Integer.toString(
                                                 ((Evaluator.IntegerValue)value).value()))));
        values.put("failwith", new Evaluator.Builtin((value, position) -> {
            throw new Evaluator.RuntimeFailure(position, "failure " + printValue(value));
        }));
        return new Environments(types, values);
    }
    record Leading(List<String> parameters, Parser.Expr body) {}
    static Leading leading(Parser.Expr expression) {
        List<String> parameters = new ArrayList<>();
        while (expression instanceof Parser.Fun function) {
            parameters.add(function.parameter().spelling());
            expression = function.body();
        }
        return new Leading(parameters, expression);
    }
    static String formatBinding(Parser.Binding binding) {
        Leading leading = leading(binding.expression);
        StringJoiner parts = new StringJoiner(" ");
        parts.add(binding.name());
        for (String parameter : leading.parameters())
            parts.add(parameter);
        parts.add("=");
        parts.add(formatExpression(leading.body(), 0));
        return parts.toString();
    }
    static String formatGroup(Parser.Group group) {
        StringJoiner bindings = new StringJoiner(" and ");
        for (Parser.Binding binding : group.bindings())
            bindings.add(formatBinding(binding));
        return (group.recPosition() == null ? "let " : "let rec ") + bindings;
    }
    static boolean endsWithMatch(Parser.Expr expression) {
        return switch (expression) {
            case Parser.Match ignored -> true;
            case Parser.Let let -> endsWithMatch(let.body());
            case Parser.Fun function -> endsWithMatch(function.body());
            case Parser.Conditional conditional -> endsWithMatch(conditional.no());
            default -> false;
        };
    }
    static String printLiteral(String kind, String value) {
        return kind.equals("string") ? quoted(value) : value;
    }
    static String formatPattern(Parser.Pattern pattern) {
        return switch (pattern) {
            case Parser.Wildcard ignored -> "_";
            case Parser.PatternName name -> name.token().spelling();
            case Parser.PatternLiteral literal -> printLiteral(literal.kind(), literal.value());
            case Parser.PatternPair pair ->
                "(" + formatPattern(pair.first()) + ", " + formatPattern(pair.second()) + ")";
            case Parser.PatternList list -> {
                StringJoiner elements = new StringJoiner("; ");
                for (Parser.Pattern child : list.elements())
                    elements.add(formatPattern(child));
                yield "[" + elements + "]";
            }
            case Parser.Cons cons -> {
                String first = formatPattern(cons.first());
                yield(cons.first() instanceof Parser.Cons ? "(" + first + ")" : first) +
                    " :: " + formatPattern(cons.rest());
            }
        };
    }
    static int strength(Parser.Expr expression) {
        if (expression instanceof Parser.Let || expression instanceof Parser.Fun ||
            expression instanceof Parser.Conditional || expression instanceof Parser.Match)
            return 0;
        if (expression instanceof Parser.Binary binary)
            return Parser.OPERATORS.get(binary.operator().spelling()).precedence();
        if (expression instanceof Parser.Negate)
            return 7;
        return expression instanceof Parser.Apply ? 8 : 9;
    }
    static String formatExpression(Parser.Expr expression, int minimum) {
        String text = switch (expression) {
            case Parser.Literal literal -> printLiteral(literal.kind(), literal.value());
            case Parser.Name name -> name.token().spelling();
            case Parser.Fun function -> {
                Leading leading = leading(function);
                yield "fun " + String.join(" ", leading.parameters()) + " -> " +
                    formatExpression(leading.body(), 0);
            }
            case Parser.Apply application ->
                formatExpression(application.function(), 8) + " " +
                    formatExpression(application.argument(), 9);
            case Parser.Binary binary -> {
                Parser.Operator operator = Parser.OPERATORS.get(binary.operator().spelling());
                yield formatExpression(binary.left(),
                                       operator.precedence() + (operator.right() ? 1 : 0)) +
                    " " + binary.operator().spelling() + " " +
                    formatExpression(binary.right(),
                                     operator.precedence() + (operator.right() ? 0 : 1));
            }
            case Parser.Negate negate -> "-" + formatExpression(negate.operand(), 7);
            case Parser.Conditional conditional ->
                "if " + formatExpression(conditional.condition(), 0) + " then " +
                    formatExpression(conditional.yes(), 0) + " else " +
                    formatExpression(conditional.no(), 0);
            case Parser.Pair pair ->
                "(" + formatExpression(pair.first(), 0) + ", " +
                    formatExpression(pair.second(), 0) + ")";
            case Parser.ListExpr list -> {
                StringJoiner elements = new StringJoiner("; ");
                for (Parser.Expr child : list.elements())
                    elements.add(formatExpression(child, 0));
                yield "[" + elements + "]";
            }
            case Parser.Let let ->
                formatGroup(let.group()) + " in " + formatExpression(let.body(), 0);
            case Parser.Match match -> {
                StringJoiner arms = new StringJoiner(" | ");
                for (int i = 0; i < match.arms().size(); i++) {
                    Parser.Arm arm = match.arms().get(i);
                    String body = formatExpression(arm.expression(), 0);
                    if (i + 1 < match.arms().size() && endsWithMatch(arm.expression()))
                        body = "(" + body + ")";
                    arms.add(formatPattern(arm.pattern()) + " -> " + body);
                }
                yield "match " + formatExpression(match.matched(), 0) + " with " + arms;
            }
        };
        return strength(expression) < minimum ? "(" + text + ")" : text;
    }
    static String formatItem(Parser.Item item) {
        return switch (item) {
            case Parser.Signature signature ->
                "val " + signature.name().spelling() + " : " +
                    formatDeclared(signature.declared()) + ";;";
            case Parser.Declaration declaration -> formatGroup(declaration.group()) + ";;";
            case Parser.ExpressionItem expression ->
                formatExpression(expression.expression(), 0) + ";;";
        };
    }
    record CoverageType(String kind, List<CoverageType> children) {}
    record Constructor(String kind, String value) {}
    record CoveragePattern(Constructor constructor, List<CoveragePattern> arguments) {}
    static final CoveragePattern ANY = new CoveragePattern(new Constructor("*", ""), List.of());
    static final Constructor NIL = new Constructor("nil", ""), CONS = new Constructor("cons", ""),
                             PAIR = new Constructor("pair", "");
    static CoverageType coverageType(Unifier.Type type) {
        type = Unifier.resolve(type);
        if (type instanceof Unifier.Variable)
            return new CoverageType("opaque", List.of());
        Unifier.Construct constructor = (Unifier.Construct)type;
        if (constructor.kind().equals("function"))
            return new CoverageType("opaque", List.of());
        List<CoverageType> children = new ArrayList<>();
        for (Unifier.Type child : constructor.children())
            children.add(coverageType(child));
        return new CoverageType(constructor.kind(), List.copyOf(children));
    }
    static CoveragePattern coveragePattern(Parser.Pattern pattern) {
        if (pattern instanceof Parser.Wildcard || pattern instanceof Parser.PatternName)
            return ANY;
        if (pattern instanceof Parser.PatternLiteral literal)
            return new CoveragePattern(new Constructor(literal.kind(), literal.value()), List.of());
        if (pattern instanceof Parser.PatternList list) {
            CoveragePattern result = new CoveragePattern(NIL, List.of());
            for (int i = list.elements().size() - 1; i >= 0; i--)
                result = new CoveragePattern(
                    CONS, List.of(coveragePattern(list.elements().get(i)), result));
            return result;
        }
        if (pattern instanceof Parser.Cons cons)
            return new CoveragePattern(
                CONS, List.of(coveragePattern(cons.first()), coveragePattern(cons.rest())));
        Parser.PatternPair pair = (Parser.PatternPair)pattern;
        return new CoveragePattern(
            PAIR, List.of(coveragePattern(pair.first()), coveragePattern(pair.second())));
    }
    static List<Constructor> constructors(CoverageType type) {
        return switch (type.kind()) {
            case "bool" ->
                List.of(new Constructor("boolean", "false"), new Constructor("boolean", "true"));
            case "list" -> List.of(NIL, CONS);
            case "pair" -> List.of(PAIR);
            default -> List.of();
        };
    }
    static List<CoverageType> constructorArguments(Constructor constructor, CoverageType type) {
        if (constructor.equals(PAIR))
            return type.children();
        if (constructor.equals(CONS))
            return List.of(type.children().getFirst(), type);
        return List.of();
    }
    static <T> List<T> prepend(List<T> first, List<T> rest) {
        List<T> result = new ArrayList<>(first);
        result.addAll(rest);
        return List.copyOf(result);
    }
    static List<List<CoveragePattern>> specialize(List<List<CoveragePattern>> matrix,
                                                  Constructor constructor, int arity) {
        List<List<CoveragePattern>> rows = new ArrayList<>();
        for (List<CoveragePattern> row : matrix) {
            CoveragePattern first = row.getFirst();
            if (first.equals(ANY))
                rows.add(prepend(Collections.nCopies(arity, ANY), row.subList(1, row.size())));
            else if (first.constructor().equals(constructor))
                rows.add(prepend(first.arguments(), row.subList(1, row.size())));
        }
        return List.copyOf(rows);
    }
    record UsefulKey(List<List<CoveragePattern>> matrix, List<CoveragePattern> query,
                     List<CoverageType> types) {}
    static boolean useful(List<List<CoveragePattern>> matrix, List<CoveragePattern> query,
                          List<CoverageType> types, Map<UsefulKey, Boolean> cache) {
        UsefulKey key = new UsefulKey(matrix, query, types);
        Boolean previous = cache.get(key);
        if (previous != null)
            return previous;
        boolean result;
        if (query.isEmpty())
            result = matrix.isEmpty();
        else if (matrix.isEmpty())
            result = true;
        else {
            CoveragePattern first = query.getFirst();
            List<CoveragePattern> remaining = query.subList(1, query.size());
            List<CoverageType> remainingTypes = types.subList(1, types.size());
            if (!first.equals(ANY)) {
                List<CoverageType> arguments =
                    constructorArguments(first.constructor(), types.getFirst());
                result = useful(specialize(matrix, first.constructor(), first.arguments().size()),
                                prepend(first.arguments(), remaining),
                                prepend(arguments, remainingTypes), cache);
            } else {
                List<Constructor> possible = constructors(types.getFirst());
                Set<Constructor> present = new HashSet<>();
                for (List<CoveragePattern> row : matrix)
                    if (!row.getFirst().equals(ANY))
                        present.add(row.getFirst().constructor());
                if (!possible.isEmpty() && present.containsAll(possible)) {
                    result = false;
                    for (Constructor constructor : possible) {
                        List<CoverageType> arguments =
                            constructorArguments(constructor, types.getFirst());
                        if (useful(specialize(matrix, constructor, arguments.size()),
                                   prepend(Collections.nCopies(arguments.size(), ANY), remaining),
                                   prepend(arguments, remainingTypes), cache)) {
                            result = true;
                            break;
                        }
                    }
                } else {
                    List<List<CoveragePattern>> defaults = new ArrayList<>();
                    for (List<CoveragePattern> row : matrix)
                        if (row.getFirst().equals(ANY))
                            defaults.add(List.copyOf(row.subList(1, row.size())));
                    result = useful(List.copyOf(defaults), remaining, remainingTypes, cache);
                }
            }
        }
        cache.put(key, result);
        return result;
    }
    static List<Parser.Expr> children(Parser.Expr expression) {
        return switch (expression) {
            case Parser.Fun function -> List.of(function.body());
            case Parser.Apply application ->
                List.of(application.function(), application.argument());
            case Parser.Binary binary -> List.of(binary.left(), binary.right());
            case Parser.Negate negate -> List.of(negate.operand());
            case Parser.Conditional conditional ->
                List.of(conditional.condition(), conditional.yes(), conditional.no());
            case Parser.Pair pair -> List.of(pair.first(), pair.second());
            case Parser.ListExpr list -> list.elements();
            case Parser.Let let -> {
                List<Parser.Expr> children = new ArrayList<>();
                for (Parser.Binding binding : let.group().bindings())
                    children.add(binding.expression);
                children.add(let.body());
                yield children;
            }
            case Parser.Match match -> {
                List<Parser.Expr> children = new ArrayList<>();
                children.add(match.matched());
                for (Parser.Arm arm : match.arms())
                    children.add(arm.expression());
                yield children;
            }
            default -> List.of();
        };
    }
    static final class Symbol {
        String name;
        Lexer.Position position;
        boolean topLevel, used;
        Symbol(String name, Lexer.Position position, boolean topLevel) {
            this.name = name;
            this.position = position;
            this.topLevel = topLevel;
        }
    }
    record GroupSymbols(Parser.Group group, Set<Symbol> targets) {}
    record Warning(Lexer.Position position, int priority, String message) {}
    static final class StaticChecks {
        List<Symbol> symbols = new ArrayList<>();
        Map<Parser.Expr, Symbol> references = new IdentityHashMap<>();
        List<GroupSymbols> groups = new ArrayList<>();
        List<Warning> warnings = new ArrayList<>();
        Map<Parser.Expr, Unifier.Type> inferred;
        StaticChecks(Map<Parser.Expr, Unifier.Type> inferred) { this.inferred = inferred; }
        Symbol symbol(String name, Lexer.Position position, boolean topLevel) {
            Symbol symbol = new Symbol(name, position, topLevel);
            symbols.add(symbol);
            return symbol;
        }
        void bindPattern(Parser.Pattern pattern, Map<String, Symbol> environment) {
            switch (pattern) {
            case Parser.PatternName name ->
                environment.put(name.token().spelling(),
                                symbol(name.token().spelling(), name.position(), false));
            case Parser.PatternPair pair -> {
                bindPattern(pair.first(), environment);
                bindPattern(pair.second(), environment);
            }
            case Parser.PatternList list -> {
                for (Parser.Pattern child : list.elements())
                    bindPattern(child, environment);
            }
            case Parser.Cons cons -> {
                bindPattern(cons.first(), environment);
                bindPattern(cons.rest(), environment);
            }
            default -> {
            }
            }
        }
        Map<String, Symbol> group(Parser.Group group, Map<String, Symbol> environment,
                                  boolean topLevel) {
            List<Symbol> bound = new ArrayList<>();
            for (Parser.Binding binding : group.bindings())
                bound.add(symbol(binding.name(), binding.position(), topLevel));
            groups.add(new GroupSymbols(group, new HashSet<>(bound)));
            Map<String, Symbol> inner = new HashMap<>(environment);
            for (Symbol symbol : bound)
                inner.put(symbol.name, symbol);
            Map<String, Symbol> right = group.recPosition() == null ? environment : inner;
            for (Parser.Binding binding : group.bindings())
                expression(binding.expression, right);
            return inner;
        }
        void matchWarnings(Parser.Match match) {
            Map<UsefulKey, Boolean> cache = new HashMap<>();
            List<List<CoveragePattern>> matrix = List.of();
            List<CoverageType> types = List.of(coverageType(inferred.get(match.matched())));
            for (int i = 0; i < match.arms().size(); i++) {
                Parser.Pattern pattern = match.arms().get(i).pattern();
                List<CoveragePattern> query = List.of(coveragePattern(pattern));
                if (i > 0 && !useful(matrix, query, types, cache))
                    warnings.add(new Warning(pattern.position(), 2, "this match case is unused"));
                List<List<CoveragePattern>> expanded = new ArrayList<>(matrix);
                expanded.add(query);
                matrix = List.copyOf(expanded);
            }
            if (useful(matrix, List.of(ANY), types, cache))
                warnings.add(new Warning(match.position(), 1, "this match is not exhaustive"));
        }
        void expression(Parser.Expr expression, Map<String, Symbol> environment) {
            if (expression instanceof Parser.Name name) {
                Symbol symbol = environment.get(name.token().spelling());
                references.put(expression, symbol);
                if (symbol != null)
                    symbol.used = true;
                return;
            }
            if (expression instanceof Parser.Fun function) {
                Map<String, Symbol> inner = new HashMap<>(environment);
                String parameter = function.parameter().spelling();
                if (!parameter.equals("_"))
                    inner.put(parameter, symbol(parameter, function.parameter().position(), false));
                expression(function.body(), inner);
                return;
            }
            if (expression instanceof Parser.Let let) {
                expression(let.body(), group(let.group(), environment, false));
                return;
            }
            if (expression instanceof Parser.Match match) {
                expression(match.matched(), environment);
                matchWarnings(match);
                for (Parser.Arm arm : match.arms()) {
                    Map<String, Symbol> inner = new HashMap<>(environment);
                    bindPattern(arm.pattern(), inner);
                    expression(arm.expression(), inner);
                }
                return;
            }
            for (Parser.Expr child : children(expression))
                expression(child, environment);
        }
        boolean hasReference(Parser.Expr expression, Set<Symbol> targets) {
            if (targets.contains(references.get(expression)))
                return true;
            for (Parser.Expr child : children(expression))
                if (hasReference(child, targets))
                    return true;
            return false;
        }
        void tailCalls(Parser.Expr expression, boolean tail, Set<Symbol> targets,
                       List<Boolean> calls) {
            if (expression instanceof Parser.Name) {
                if (targets.contains(references.get(expression)))
                    calls.add(false);
                return;
            }
            if (expression instanceof Parser.Apply) {
                List<Parser.Expr> arguments = new ArrayList<>();
                Parser.Expr function = expression;
                while (function instanceof Parser.Apply application) {
                    arguments.add(application.argument());
                    function = application.function();
                }
                if (function instanceof Parser.Name && targets.contains(references.get(function)))
                    calls.add(tail);
                else
                    tailCalls(function, false, targets, calls);
                for (int i = arguments.size() - 1; i >= 0; i--)
                    tailCalls(arguments.get(i), false, targets, calls);
                return;
            }
            if (expression instanceof Parser.Conditional conditional) {
                tailCalls(conditional.condition(), false, targets, calls);
                tailCalls(conditional.yes(), tail, targets, calls);
                tailCalls(conditional.no(), tail, targets, calls);
                return;
            }
            if (expression instanceof Parser.Match match) {
                tailCalls(match.matched(), false, targets, calls);
                for (Parser.Arm arm : match.arms())
                    tailCalls(arm.expression(), tail, targets, calls);
                return;
            }
            if (expression instanceof Parser.Let let) {
                for (Parser.Binding binding : let.group().bindings())
                    tailCalls(binding.expression, false, targets, calls);
                tailCalls(let.body(), tail, targets, calls);
                return;
            }
            if (expression instanceof Parser.Binary binary &&
                Set.of("&&", "||").contains(binary.operator().spelling())) {
                tailCalls(binary.left(), false, targets, calls);
                tailCalls(binary.right(), tail, targets, calls);
                return;
            }
            for (Parser.Expr child : children(expression))
                tailCalls(child, false, targets, calls);
        }
        List<Warning> item(Parser.Item item, Set<String> environmentNames) {
            Map<String, Symbol> environment = new HashMap<>();
            for (String name : environmentNames)
                environment.put(name, null);
            if (item instanceof Parser.Declaration declaration)
                group(declaration.group(), environment, true);
            else
                expression(((Parser.ExpressionItem)item).expression(), environment);
            for (GroupSymbols entry : groups) {
                Parser.Group group = entry.group();
                if (group.recPosition() == null)
                    continue;
                boolean referenced = false;
                for (Parser.Binding binding : group.bindings())
                    if (hasReference(binding.expression, entry.targets()))
                        referenced = true;
                if (!referenced)
                    warnings.add(new Warning(group.recPosition(), 3, "unused rec flag"));
                for (Parser.Binding binding : group.bindings()) {
                    List<Boolean> calls = new ArrayList<>();
                    tailCalls(leading(binding.expression).body(), true, entry.targets(), calls);
                    binding.classification = calls.isEmpty() ? ""
                                             : calls.stream().allMatch(Boolean::booleanValue)
                                                 ? "tail recursive"
                                                 : "recursive";
                }
            }
            for (Symbol symbol : symbols)
                if (!symbol.topLevel && !symbol.used && !symbol.name.startsWith("_"))
                    warnings.add(
                        new Warning(symbol.position, 4, "unused variable '" + symbol.name + "'"));
            warnings.sort(
                Comparator.comparing(Warning::position).thenComparingInt(Warning::priority));
            return warnings;
        }
    }
    static String classification(Parser.Binding binding) {
        return binding.classification.isEmpty() ? "" : " (" + binding.classification + ")";
    }
    static String syntaxError(Lexer.Token token) {
        return token.kind().equals("invalid") ? token.value()
        : token.kind().equals("EOF")          ? "unexpected end of file"
                                              : "unexpected '" + token.spelling() + "'";
    }
    static final class Counts {
        int items, bindings, syntax, type, runtime, warnings, calls;
        public String toString() {
            return "items=" + items + " bindings=" + bindings + " syntax=" + syntax +
                " type=" + type + " runtime=" + runtime + " warnings=" + warnings +
                " calls=" + calls;
        }
    }
    static final class Reports {
        Map<String, List<String>> sources = new LinkedHashMap<>();
        Map<String, Counts> statistics = new LinkedHashMap<>();
        List<String> lines = new ArrayList<>();
        String currentFile;
        Reports(Map<String, String> sources) {
            for (var entry : sources.entrySet()) {
                this.sources.put(
                    entry.getKey(),
                    entry.getValue().isEmpty()
                        ? List.of()
                        : Arrays.asList(entry.getValue()
                                            .substring(0, entry.getValue().length() - 1)
                                            .split("\n", -1)));
                statistics.put(entry.getKey(), new Counts());
            }
        }
        void report(String kind, Lexer.Position position, String message) {
            Counts counts = statistics.get(currentFile);
            switch (kind) {
            case "syntax error" -> counts.syntax++;
            case "type error" -> counts.type++;
            case "runtime error" -> counts.runtime++;
            case "warning" -> counts.warnings++;
            }
            lines.add(position.file() + ":" + position.line() + ":" + position.column() + ": " +
                      kind + ": " + message);
            List<String> source = sources.get(position.file());
            if (position.line() <= source.size()) {
                lines.add("    " + source.get(position.line() - 1));
                lines.add(" ".repeat(position.column() + 3) + "^");
            }
        }
        void finish() {
            lines.add("== summary ==");
            for (var entry : statistics.entrySet())
                lines.add(entry.getKey() + ": " + entry.getValue());
        }
    }
    static final class MiniMl {
        Map<String, String> sources;
        Map<String, Unifier.Scheme> typeEnvironment;
        Map<String, Evaluator.Value> valueEnvironment;
        Reports reports;
        List<String> types = new ArrayList<>(), values = new ArrayList<>(),
                     formatted = new ArrayList<>();
        MiniMl(Map<String, String> sources) {
            this.sources = sources;
            Environments builtins = builtins();
            typeEnvironment = builtins.types();
            valueEnvironment = builtins.values();
            reports = new Reports(sources);
        }
        void unusedSignature(Parser.Signature signature) {
            reports.report("warning", signature.name().position(),
                           "signature for '" + signature.name().spelling() + "' is never used");
        }
        void writeTypes(Parser.Item item, Unifier.Type inferred, List<Parser.Binding> local) {
            if (item instanceof Parser.Declaration declaration)
                for (Parser.Binding binding : declaration.group().bindings())
                    types.add(binding.name() + " : " +
                              new TypePrinter().print(binding.scheme.value()) +
                              classification(binding));
            else
                types.add("- : " + new TypePrinter().print(inferred));
            List<Parser.Binding> ordered = new ArrayList<>(local);
            ordered.sort(Comparator.comparing(Parser.Binding::position));
            for (Parser.Binding binding : ordered) {
                Lexer.Position position = binding.position();
                types.add(
                    "  " + binding.name() + " (" + position.line() + ":" + position.column() +
                    ") : " +
                    new TypePrinter(binding.scheme.quantified()).print(binding.scheme.value()) +
                    classification(binding));
            }
        }
        void processItem(Parser.Item item, Map<String, Parser.Signature> pending,
                         Evaluator evaluator, Counts counts) {
            formatted.add(formatItem(item));
            if (item instanceof Parser.Signature signature) {
                String name = signature.name().spelling();
                Parser.Signature previous = pending.put(name, signature);
                if (previous != null)
                    unusedSignature(previous);
                return;
            }
            List<Parser.Signature> signatures = new ArrayList<>();
            if (item instanceof Parser.Declaration declaration)
                for (Parser.Binding binding : declaration.group().bindings())
                    signatures.add(pending.remove(binding.name()));
            Inference inference = new Inference();
            Unifier.Type inferred = null;
            try {
                if (item instanceof Parser.Declaration declaration) {
                    inference.group(declaration.group(), typeEnvironment, false);
                    checkSignatures(declaration.group(), signatures);
                } else
                    inferred = inference.expression(((Parser.ExpressionItem)item).expression(),
                                                    typeEnvironment);
            } catch (Inference.Error error) {
                reports.report("type error", error.position, typeError(error));
                return;
            }
            List<Warning> warnings =
                new StaticChecks(inference.inferred).item(item, typeEnvironment.keySet());
            writeTypes(item, inferred, inference.localBindings);
            for (Warning warning : warnings)
                reports.report("warning", warning.position(), warning.message());
            Map<String, Evaluator.Value> environment = null;
            Evaluator.Value value = null;
            try {
                if (item instanceof Parser.Declaration declaration)
                    environment = evaluator.group(declaration.group(), valueEnvironment);
                else
                    value = evaluator.expression(((Parser.ExpressionItem)item).expression(),
                                                 valueEnvironment);
            } catch (Evaluator.RuntimeFailure error) {
                reports.report("runtime error", error.position, error.getMessage());
                return;
            }
            if (item instanceof Parser.Declaration declaration) {
                Map<String, Unifier.Scheme> newTypes = new HashMap<>(typeEnvironment);
                for (Parser.Binding binding : declaration.group().bindings()) {
                    values.add(binding.name() + " = " +
                               printValue(environment.get(binding.name())));
                    newTypes.put(binding.name(), binding.scheme);
                }
                typeEnvironment = newTypes;
                valueEnvironment = environment;
                counts.bindings += declaration.group().bindings().size();
            } else
                values.add("- = " + printValue(value));
        }
        void processFile(String file) {
            reports.currentFile = file;
            Counts counts = reports.statistics.get(file);
            types.add("== " + file + " ==");
            values.add("== " + file + " ==");
            formatted.add("(* " + file + " *)");
            Map<String, Parser.Signature> pending = new HashMap<>();
            Evaluator evaluator = new Evaluator();
            Parser parser = new Parser(Lexer.tokenize(sources.get(file), file));
            while (!parser.peek().kind().equals("EOF")) {
                counts.items++;
                Parser.Item item;
                try {
                    item = parser.item();
                } catch (Parser.SyntaxFailure failure) {
                    reports.report("syntax error", failure.token.position(),
                                   syntaxError(failure.token));
                    parser.recover();
                    continue;
                }
                processItem(item, pending, evaluator, counts);
            }
            List<Parser.Signature> unused = new ArrayList<>(pending.values());
            unused.sort(Comparator.comparing(signature -> signature.name().position()));
            for (Parser.Signature signature : unused)
                unusedSignature(signature);
            counts.calls = evaluator.calls;
        }
        void run() throws Exception {
            for (String file : sources.keySet())
                processFile(file);
            reports.finish();
            Files.createDirectories(Path.of("output"));
            write("types.txt", types);
            write("values.txt", values);
            write("errors.txt", reports.lines);
            write("formatted.ml", formatted);
        }
    }
    static void write(String file, List<String> lines) throws Exception {
        Files.writeString(Path.of("output", file), String.join("\n", lines) + "\n",
                          StandardCharsets.US_ASCII);
    }
    public static void main(String[] args) throws Exception {
        Map<String, String> sources = new LinkedHashMap<>();
        for (String file : List.of("prelude.ml", "program.ml"))
            sources.put(file, Files.readString(Path.of("input", file), StandardCharsets.US_ASCII));
        new MiniMl(sources).run();
    }
}

import java.util.*;
final class Parser {
    sealed interface Expr permits Literal, Name, Fun, Apply, Binary, Negate, Conditional, Pair,
        ListExpr, Let, Match {
        Lexer.Position position();
    }
    record Literal(String kind, String value, Lexer.Position position) implements Expr {}
    record Name(Lexer.Token token) implements Expr {
        public Lexer.Position position() { return token.position(); }
    }
    record Fun(Lexer.Token parameter, Expr body, Lexer.Position position) implements Expr {}
    record Apply(Expr function, Expr argument) implements Expr {
        public Lexer.Position position() { return function.position(); }
    }
    record Binary(Expr left, Lexer.Token operator, Expr right) implements Expr {
        public Lexer.Position position() { return left.position(); }
    }
    record Negate(Lexer.Token operator, Expr operand) implements Expr {
        public Lexer.Position position() { return operator.position(); }
    }
    record Conditional(Expr condition, Expr yes, Expr no, Lexer.Position position) implements Expr {
    }
    record Pair(Expr first, Expr second, Lexer.Position position) implements Expr {}
    record ListExpr(List<Expr> elements, Lexer.Position position) implements Expr {}
    record Let(Group group, Expr body, Lexer.Position position) implements Expr {}
    record Match(Expr matched, List<Arm> arms, Lexer.Position position) implements Expr {}
    sealed interface Pattern permits Wildcard, PatternName, PatternLiteral, PatternPair,
        PatternList, Cons {
        Lexer.Position position();
    }
    record Wildcard(Lexer.Position position) implements Pattern {}
    record PatternName(Lexer.Token token) implements Pattern {
        public Lexer.Position position() { return token.position(); }
    }
    record PatternLiteral(String kind, String value, Lexer.Position position) implements Pattern {}
    record PatternPair(Pattern first, Pattern second, Lexer.Position position) implements Pattern {}
    record PatternList(List<Pattern> elements, Lexer.Position position) implements Pattern {}
    record Cons(Pattern first, Pattern rest) implements Pattern {
        public Lexer.Position position() { return first.position(); }
    }
    record Arm(Pattern pattern, Expr expression) {}
    static final class Binding {
        Lexer.Token token;
        Expr expression;
        Unifier.Scheme scheme;
        String classification = "";
        Binding(Lexer.Token token, Expr expression) {
            this.token = token;
            this.expression = expression;
        }
        String name() { return token.spelling(); }
        Lexer.Position position() { return token.position(); }
    }
    record Group(List<Binding> bindings, Lexer.Position recPosition) {}
    sealed interface TypeExpr permits TypeName, TypeVariableName, TypeConstructor {}
    record TypeName(String name) implements TypeExpr {}
    record TypeVariableName(String spelling) implements TypeExpr {}
    record TypeConstructor(String kind, List<TypeExpr> children) implements TypeExpr {}
    sealed interface Item permits Signature, Declaration, ExpressionItem {}
    record Signature(Lexer.Token name, TypeExpr declared) implements Item {}
    record Declaration(Group group) implements Item {}
    record ExpressionItem(Expr expression) implements Item {}
    record Operator(int precedence, boolean right) {}
    static final Map<String, Operator> OPERATORS = operators();
    static Map<String, Operator> operators() {
        Map<String, Operator> result = new HashMap<>();
        String[][] groups = {{"||"},      {"&&"},     {"=", "<>", "<", ">", "<=", ">="},
                             {"::", "^"}, {"+", "-"}, {"*", "/", "mod"}};
        for (int i = 0; i < groups.length; i++)
            for (String operator : groups[i])
                result.put(operator, new Operator(i + 1, i == 0 || i == 1 || i == 3));
        return Map.copyOf(result);
    }
    static final class SyntaxFailure extends RuntimeException {
        Lexer.Token token;
        SyntaxFailure(Lexer.Token token) { this.token = token; }
    }
    List<Lexer.Token> tokens;
    int index;
    Parser(List<Lexer.Token> tokens) { this.tokens = tokens; }
    Lexer.Token peek() { return tokens.get(index); }
    Lexer.Token accept(String kind) {
        return peek().kind().equals(kind) ? tokens.get(index++) : null;
    }
    Lexer.Token expect(String kind) {
        Lexer.Token token = accept(kind);
        if (token == null)
            throw new SyntaxFailure(peek());
        return token;
    }
    Lexer.Token name() {
        if (!peek().isName())
            throw new SyntaxFailure(peek());
        return expect("identifier");
    }
    void recover() {
        while (!Set.of(";;", "EOF").contains(peek().kind()))
            index++;
        accept(";;");
    }
    Item item() {
        if (accept("val") != null) {
            Lexer.Token name = name();
            expect(":");
            TypeExpr declared = typeExpression();
            expect(";;");
            return new Signature(name, declared);
        }
        Lexer.Token opening = accept("let");
        Item item;
        if (opening != null) {
            Group group = group();
            item = accept("in") != null
                       ? new ExpressionItem(new Let(group, expression(), opening.position()))
                       : new Declaration(group);
        } else
            item = new ExpressionItem(expression());
        expect(";;");
        return item;
    }
    Group group() {
        Lexer.Token rec = accept("rec");
        List<Binding> bindings = new ArrayList<>();
        bindings.add(binding());
        while (accept("and") != null)
            bindings.add(binding());
        return new Group(bindings, rec == null ? null : rec.position());
    }
    Binding binding() {
        Lexer.Token name = name();
        List<Lexer.Token> parameters = new ArrayList<>();
        while (peek().kind().equals("identifier"))
            parameters.add(expect("identifier"));
        expect("=");
        Expr expression = expression();
        for (int i = parameters.size() - 1; i >= 0; i--)
            expression = new Fun(parameters.get(i), expression, parameters.get(i).position());
        return new Binding(name, expression);
    }
    Expr expression() {
        Lexer.Token opening = accept("let");
        if (opening != null) {
            Group group = group();
            expect("in");
            return new Let(group, expression(), opening.position());
        }
        opening = accept("fun");
        if (opening != null) {
            List<Lexer.Token> parameters = new ArrayList<>();
            parameters.add(expect("identifier"));
            while (peek().kind().equals("identifier"))
                parameters.add(expect("identifier"));
            expect("->");
            Expr expression = expression();
            for (int i = parameters.size() - 1; i >= 0; i--)
                expression = new Fun(parameters.get(i), expression,
                                     i == 0 ? opening.position() : parameters.get(i).position());
            return expression;
        }
        opening = accept("if");
        if (opening != null) {
            Expr condition = expression();
            expect("then");
            Expr yes = expression();
            expect("else");
            return new Conditional(condition, yes, expression(), opening.position());
        }
        opening = accept("match");
        if (opening != null) {
            Expr matched = expression();
            expect("with");
            accept("|");
            List<Arm> arms = new ArrayList<>();
            arms.add(arm());
            while (accept("|") != null)
                arms.add(arm());
            return new Match(matched, arms, opening.position());
        }
        return binary(1);
    }
    Arm arm() {
        Pattern pattern = pattern();
        expect("->");
        return new Arm(pattern, expression());
    }
    Expr binary(int minimum) {
        Expr expression = unary();
        while (OPERATORS.containsKey(peek().kind())) {
            Operator operator = OPERATORS.get(peek().kind());
            if (operator.precedence() < minimum)
                break;
            Lexer.Token token = tokens.get(index++);
            Expr right = binary(operator.precedence() + (operator.right() ? 0 : 1));
            expression = new Binary(expression, token, right);
        }
        return expression;
    }
    boolean startsAtom() {
        return Set.of("integer", "string", "true", "false", "(", "[").contains(peek().kind()) ||
            peek().isName();
    }
    Expr unary() {
        Lexer.Token operator = accept("-");
        if (operator != null)
            return new Negate(operator, unary());
        Expr expression = atom();
        while (startsAtom())
            expression = new Apply(expression, atom());
        return expression;
    }
    Expr atom() {
        Lexer.Token token = peek();
        if (Set.of("integer", "string", "true", "false").contains(token.kind())) {
            index++;
            return new Literal(token.kind().equals("true") || token.kind().equals("false")
                                   ? "boolean"
                                   : token.kind(),
                               token.value(), token.position());
        }
        if (token.isName()) {
            index++;
            return new Name(token);
        }
        if (accept("(") != null) {
            Expr first = expression();
            if (accept(",") != null) {
                Expr second = expression();
                expect(")");
                return new Pair(first, second, token.position());
            }
            expect(")");
            return first;
        }
        if (accept("[") != null) {
            List<Expr> elements = new ArrayList<>();
            if (accept("]") == null) {
                elements.add(expression());
                while (accept(";") != null)
                    elements.add(expression());
                expect("]");
            }
            return new ListExpr(elements, token.position());
        }
        throw new SyntaxFailure(token);
    }
    Pattern pattern() {
        Pattern first = patternAtom();
        return accept("::") != null ? new Cons(first, pattern()) : first;
    }
    Pattern patternAtom() {
        Lexer.Token token = peek();
        if (token.kind().equals("identifier")) {
            index++;
            return token.spelling().equals("_") ? new Wildcard(token.position())
                                                : new PatternName(token);
        }
        if (accept("-") != null) {
            Lexer.Token integer = expect("integer");
            return new PatternLiteral("integer", Long.toString(-Long.parseLong(integer.value())),
                                      token.position());
        }
        if (Set.of("integer", "string", "true", "false").contains(token.kind())) {
            index++;
            return new PatternLiteral(token.kind().equals("true") || token.kind().equals("false")
                                          ? "boolean"
                                          : token.kind(),
                                      token.value(), token.position());
        }
        if (accept("(") != null) {
            Pattern first = pattern();
            if (accept(",") != null) {
                Pattern second = pattern();
                expect(")");
                return new PatternPair(first, second, token.position());
            }
            expect(")");
            return first;
        }
        if (accept("[") != null) {
            List<Pattern> elements = new ArrayList<>();
            if (accept("]") == null) {
                elements.add(pattern());
                while (accept(";") != null)
                    elements.add(pattern());
                expect("]");
            }
            return new PatternList(elements, token.position());
        }
        throw new SyntaxFailure(token);
    }
    TypeExpr typeExpression() {
        TypeExpr first = listType();
        if (accept("*") != null)
            first = new TypeConstructor("pair", List.of(first, listType()));
        if (accept("->") != null)
            first = new TypeConstructor("function", List.of(first, typeExpression()));
        return first;
    }
    TypeExpr listType() {
        TypeExpr expression = typeAtom();
        while (peek().kind().equals("identifier") && peek().spelling().equals("list")) {
            index++;
            expression = new TypeConstructor("list", List.of(expression));
        }
        return expression;
    }
    TypeExpr typeAtom() {
        Lexer.Token token = peek();
        if (token.kind().equals("identifier") &&
            Set.of("int", "bool", "string").contains(token.spelling())) {
            index++;
            return new TypeName(token.spelling());
        }
        if (accept("type_variable") != null)
            return new TypeVariableName(token.spelling());
        if (accept("(") != null) {
            TypeExpr expression = typeExpression();
            expect(")");
            return expression;
        }
        throw new SyntaxFailure(token);
    }
}

import java.util.*;
final class Unifier {
    sealed interface Type permits Variable, Construct {}
    static final class Variable implements Type {
        Type binding;
    }
    record Construct(String kind, List<Type> children) implements Type {
        Construct(String kind, Type... children) { this(kind, List.of(children)); }
    }
    record Scheme(Type value, Set<Variable> quantified) {
        Scheme(Type value) { this(value, Set.of()); }
        Scheme { quantified = Set.copyOf(quantified); }
    }
    static final Construct INT = new Construct("int"), BOOL = new Construct("bool"),
                           STRING = new Construct("string");
    static Type resolve(Type value) {
        List<Variable> path = new ArrayList<>();
        while (value instanceof Variable variable && variable.binding != null) {
            path.add(variable);
            value = variable.binding;
        }
        for (Variable variable : path)
            variable.binding = value;
        return value;
    }
    static boolean occurs(Variable variable, Type value) {
        value = resolve(value);
        if (value instanceof Variable other)
            return variable == other;
        for (Type child : ((Construct)value).children())
            if (occurs(variable, child))
                return true;
        return false;
    }
    static final class Failure extends RuntimeException {
        Type expected, found;
        boolean infinite, nested;
        Failure(Type expected, Type found, boolean infinite, boolean nested) {
            this.expected = expected;
            this.found = found;
            this.infinite = infinite;
            this.nested = nested;
        }
    }
    static void unify(Type expected, Type found) { unify(expected, found, false); }
    static void unify(Type expected, Type found, boolean nested) {
        expected = resolve(expected);
        found = resolve(found);
        if (expected == found)
            return;
        if (expected instanceof Variable variable) {
            if (occurs(variable, found))
                throw new Failure(expected, found, true, nested);
            variable.binding = found;
            return;
        }
        if (found instanceof Variable variable) {
            if (occurs(variable, expected))
                throw new Failure(expected, found, true, nested);
            variable.binding = expected;
            return;
        }
        Construct first = (Construct)expected, second = (Construct)found;
        if (!first.kind().equals(second.kind()))
            throw new Failure(expected, found, false, nested);
        for (int i = 0; i < first.children().size(); i++)
            unify(first.children().get(i), second.children().get(i), true);
    }
    static Set<Variable> free(Type value) {
        value = resolve(value);
        if (value instanceof Variable variable)
            return new HashSet<>(Set.of(variable));
        Set<Variable> result = new HashSet<>();
        for (Type child : ((Construct)value).children())
            result.addAll(free(child));
        return result;
    }
    static Scheme generalize(Type value, Map<String, Scheme> environment) {
        Set<Variable> available = free(value);
        for (Scheme scheme : environment.values()) {
            Set<Variable> variables = free(scheme.value());
            variables.removeAll(scheme.quantified());
            available.removeAll(variables);
        }
        return new Scheme(value, available);
    }
    static Type instantiate(Scheme scheme) {
        return copy(scheme.value(), scheme.quantified(), new IdentityHashMap<>());
    }
    static Type copy(Type value, Set<Variable> quantified, Map<Variable, Variable> replacements) {
        value = resolve(value);
        if (value instanceof Variable variable)
            return quantified.contains(variable)
                ? replacements.computeIfAbsent(variable, ignored -> new Variable())
                : variable;
        Construct construct = (Construct)value;
        List<Type> children = new ArrayList<>();
        for (Type child : construct.children())
            children.add(copy(child, quantified, replacements));
        return new Construct(construct.kind(), children);
    }
}
